const paths = [
  "/Users/pfleidi/.agents/skills/using-superpowers/SKILL.md",
  "/Users/pfleidi/.agents/skills/pfleidi/skills/issue-alignment/SKILL.md",
  "/Users/pfleidi/.agents/skills/using-entire/SKILL.md",
  "/Users/pfleidi/.agents/skills/brainstorming/SKILL.md",
  "/Users/pfleidi/.agents/skills/writing-plans/SKILL.md"
];
const rs = await Promise.all(paths.map(path => tools.exec_command({
  cmd: `sed -n '1,240p' '${path}'`,
  workdir: "/Users/pfleidi/entire/cli",
  yield_time_ms: 10000,
  max_output_tokens: 12000
})));
rs.forEach((r, i) => { text(`FILE ${paths[i]}\n${r.output}`); });

const cmds = [
  ["codex-tools", "sed -n '1,260p' /Users/pfleidi/.agents/skills/using-superpowers/references/codex-tools.md"],
  ["brainstorming-1", "sed -n '1,220p' /Users/pfleidi/.agents/skills/brainstorming/SKILL.md"],
  ["brainstorming-2", "sed -n '221,500p' /Users/pfleidi/.agents/skills/brainstorming/SKILL.md"],
  ["issue-1", "sed -n '1,220p' /Users/pfleidi/.agents/skills/pfleidi/skills/issue-alignment/SKILL.md"],
  ["issue-2", "sed -n '221,500p' /Users/pfleidi/.agents/skills/pfleidi/skills/issue-alignment/SKILL.md"],
  ["entire", "sed -n '1,320p' /Users/pfleidi/.agents/skills/using-entire/SKILL.md"],
  ["plans", "sed -n '1,360p' /Users/pfleidi/.agents/skills/writing-plans/SKILL.md"]
];
const rs = await Promise.all(cmds.map(([_, cmd]) => tools.exec_command({
  cmd,
  workdir: "/Users/pfleidi/entire/cli",
  yield_time_ms: 10000,
  max_output_tokens: 10000
})));
rs.forEach((r, i) => text(`=== ${cmds[i][0]} ===\n${r.output}`));

