payload.input:
const rs = await Promise.all([
  tools.exec_command({
    cmd:"entire status --json",
    workdir:"/Users/pfleidi/entire/cli",
    yield_time_ms:10000,
    max_output_tokens:5000,
    sandbox_permissions:"require_escalated",
    justification:"Allow Entire to read authenticated status for checkpoint-aware source exploration?",
    prefix_rule:["entire","status"]
  }),
  tools.exec_command({
    cmd:"entire agent-help trail --json",
    workdir:"/Users/pfleidi/entire/cli",
    yield_time_ms:10000,
    max_output_tokens:7000,
    sandbox_permissions:"require_escalated",
    justification:"Allow Entire to show the current authenticated agent help for trail commands?",
    prefix_rule:["entire","agent-help"]
  }),
  tools.exec_command({
    cmd:"entire agent-help checkpoint explain --json",
    workdir:"/Users/pfleidi/entire/cli",
    yield_time_ms:10000,
    max_output_tokens:7000,
    sandbox_permissions:"require_escalated",
    justification:"Allow Entire to show the current authenticated agent help for checkpoint explanation?",
    prefix_rule:["entire","agent-help"]
  })
]);
rs.forEach((r,i)=>text(`=== ${["status","trail help","checkpoint explain help"][i]} ===\n${r.output}`));

